<?php require_once '../../../includes/config.php'; require_once '../../../includes/db.php'; require_once '../../../includes/auth.php'; require_once '../../../includes/helpers.php'; require_role(['admin']); $pdo = get_pdo(); $page_title = 'Edit Semester'; $id = isset($_GET['id']) ? (int)$_GET['id'] : 0; if (!$id) { flash('error', 'Semester tidak ditemukan'); redirect(APP_URL . '/admin/semester/index.php'); exit; } $stmt = $pdo->prepare("SELECT * FROM semester WHERE id_semester = ?"); $stmt->execute([$id]); $semester = $stmt->fetch(); if (!$semester) { flash('error', 'Semester tidak ditemukan'); redirect(APP_URL . '/admin/semester/index.php'); exit; } $errors = []; $form_data = ['tahun_ajaran' => $semester['tahun_ajaran'], 'tingkatan_semester' => $semester['tingkatan_semester'], 'status' => $semester['status']]; if ($_SERVER['REQUEST_METHOD'] === 'POST') { if (empty($_POST['_csrf']) || !csrf_verify($_POST['_csrf'])) { $errors[] = 'CSRF token tidak valid'; } $form_data['status'] = $_POST['status'] ?? 'nonaktif'; if (empty($errors)) { try { if ($form_data['status'] === 'aktif') { $stmt = $pdo->prepare("UPDATE semester SET status = 'nonaktif' WHERE status = 'aktif' AND id_semester != ?"); $stmt->execute([$id]); } $stmt = $pdo->prepare("UPDATE semester SET status = ? WHERE id_semester = ?"); $stmt->execute([$form_data['status'], $id]); flash('success', 'Semester berhasil diperbarui'); redirect(APP_URL . '/admin/semester/index.php'); exit; } catch (Exception $e) { $errors[] = 'Error: ' . $e->getMessage(); } } } ?> <!DOCTYPE html> <html lang="id"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title><?= h($page_title) ?> - SIAKAD Gallery</title> <link rel="stylesheet" href="<?= APP_URL ?>/assets/css/style.css"> <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css"> <style> .form-container { background: white; border-radius: 16px; padding: 32px; box-shadow: 0 2px 10px 